let blogDecodeWsEvent (text: string) : Result<BlogWsEvent, string> =
    match Decode.fromString (Decode.field "type" Decode.string) text with
    | Ok "NewComment" ->
        Decode.fromString (Decode.field "payload" Decode.blogNewCommentEvent) text
